function Cover({track,className=""}:{track:Track;className?:string}) { return <img src={`/art/${track.art}.webp`} alt={`${track.title} 앨범 커버`} className={`cover ${track.tint||""} ${className}`} />; }
function IconButton({label,onClick,children,active=false,className="",disabled=false}:{label:string;onClick?:()=>void;children:ReactNode;active?:boolean;className?:string;disabled?:boolean}) {return <button title={label} aria-label={label} onClick={onClick} disabled={disabled} className={`icon-button ${active?"is-active":""} ${className}`}>{children}</button>;}
function AppNavigation({view,navigate,logged,openLogin,playlistName,openPlaylist}:{playlistName:string;openPlaylist:()=>void;view:View;navigate:(v:View)=>void;logged:boolean;openLogin:()=>void}) {
 const {setOpenMobile,isMobile}=useSidebar();
 function go(v:View){navigate(v);if(isMobile)setOpenMobile(false);}
 return <Sidebar className="sori-sidebar" collapsible="offcanvas"><SidebarHeader><button onClick={()=>go("discover")} className="brand" aria-label="뮤리프 홈"><span className="muleaf-mark" aria-hidden="true"/><span className="muleaf-wordmark">muleaf</span></button><div className="brand-caption">BEYOND MUSIC</div></SidebarHeader><SidebarContent><SidebarGroup><SidebarGroupLabel>DISCOVER</SidebarGroupLabel><SidebarMenu>{navItems.slice(0,2).map(n=><SidebarMenuItem key={n.id}><SidebarMenuButton isActive={view===n.id} onClick={()=>go(n.id)} className="nav-button"><n.icon/><span>{n.label}</span></SidebarMenuButton></SidebarMenuItem>)}</SidebarMenu></SidebarGroup><SidebarGroup><SidebarGroupLabel>MY SPACE</SidebarGroupLabel><SidebarMenu>{navItems.slice(2).map(n=><SidebarMenuItem key={n.id}><SidebarMenuButton isActive={view===n.id} onClick={()=>go(n.id)} className="nav-button"><n.icon/><span>{n.label}</span></SidebarMenuButton></SidebarMenuItem>)}<SidebarMenuItem><SidebarMenuButton onClick={()=>go("upload")} isActive={view==="upload"} className="nav-button"><Plus/><span>내 음악 등록하기</span></SidebarMenuButton></SidebarMenuItem></SidebarMenu></SidebarGroup><div className="sidebar-playlists"><span>나의 플레이리스트</span><button onClick={()=>{openPlaylist();if(isMobile)setOpenMobile(false);}}><ListMusic size={17}/> {playlistName}</button></div></SidebarContent><SidebarFooter><button className="sidebar-profile" onClick={logged?()=>go("dashboard"):openLogin}><span className="avatar">{logged?"새":"S"}</span><span><strong>{logged?"새벽수집가":"나만의 소리를 찾아요"}</strong><small>{logged?"내 프로필":"간편로그인으로 시작하기"}</small></span><ChevronRight size={16}/></button></SidebarFooter></Sidebar>;
}

type MobileOptions = {
 shareTrack: (title: string, id: number) => Promise<void>;
 reportsEndpoint: string;
 localLibrary: boolean;
 blockedArtists?: string[];
 onBlockArtist?: (artist: string) => void;
 openSafety?: () => void;
};
export default function SoriApp({mobile}:{mobile?:MobileOptions} = {}){
 const [view,setView]=useState<View>("discover"); const [allTracks,setTracks]=useState<Track[]>(mobile?initialTracks.map(t=>({...t,own:false})):initialTracks);
 const tracks=allTracks.filter(t=>!mobile?.blockedArtists?.includes(t.artist));
 const [query,setQuery]=useState(""); const [genre,setGenre]=useState("전체"); const [chartPeriod,setChartPeriod]=useState("weekly"); const [homePeriod,setHomePeriod]=useState("weekly"); const [showAllRecent,setShowAllRecent]=useState(false); const [mood,setMood]=useState("전체"); const searchRef=useRef<HTMLInputElement>(null); const [searchActive,setSearchActive]=useState(false);
 const [saved,setSaved]=useState<number[]>(mobile?[]:[1,3,4,5]); const [playlist,setPlaylist]=useState<number[]>(mobile?[]:[3,1,5]); const [playlistName,setPlaylistName]=useState("밤을 채우는 소리"); const [libraryTab,setLibraryTab]=useState("saved");
 const [libraryReady,setLibraryReady]=useState(false);
 useEffect(()=>{if(!mobile?.localLibrary)return;try{const raw=localStorage.getItem("muleaf-library-v1");if(raw){const data=JSON.parse(raw);const validIds=(value:unknown):number[]=>Array.isArray(value)?[...new Set(value.filter((id):id is number=>typeof id==="number"&&initialTracks.some(t=>t.id===id)))]:[];setSaved(validIds(data.saved));setPlaylist(validIds(data.playlist));if(typeof data.name==="string"&&data.name.trim())setPlaylistName(data.name.slice(0,40));}}catch{toast("저장된 목록을 불러오지 못했어요.");}setLibraryReady(true);},[mobile?.localLibrary]);
 useEffect(()=>{if(!mobile?.localLibrary||!libraryReady)return;try{localStorage.setItem("muleaf-library-v1",JSON.stringify({saved,playlist,name:playlistName}));}catch{toast.error("기기에 목록을 저장하지 못했어요.");}},[mobile?.localLibrary,libraryReady,saved,playlist,playlistName]);
 const [reportTrack,setReportTrack]=useState<Track|null>(null); const [reportReason,setReportReason]=useState(""); const [reportDetail,setReportDetail]=useState(""); const [reportBusy,setReportBusy]=useState(false); const [reportError,setReportError]=useState(""); const [reportReceipt,setReportReceipt]=useState(""); const reportKey=useRef(""); const reportLock=useRef(false);
 function openReport(t:Track){setSelected(null);setReportTrack(t);setReportReason("");setReportDetail("");setReportError("");setReportReceipt("");reportKey.current=crypto.randomUUID();}
 async function submitReport(){if(!reportTrack||reportLock.current)return;const error=validateReport(reportReason,reportDetail);if(error){setReportError(error);return;}reportLock.current=true;setReportBusy(true);setReportError("");try{if(mobile&&!mobile.reportsEndpoint)throw new Error("앱 신고 접수 서버 연결 전입니다. 현재는 신고가 전송되지 않습니다.");const response=await fetch(mobile?.reportsEndpoint||"/api/reports",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:reportKey.current,trackId:reportTrack.id,reason:reportReason,detail:reportDetail})});const result=await response.json() as {id?:string;error?:string};if(!response.ok||!result.id)throw new Error(result.error||"신고 접수에 실패했어요.");setReportReceipt(result.id);}catch(error){setReportError(error instanceof Error?error.message:"신고를 접수하지 못했어요. 다시 시도해 주세요.");}finally{reportLock.current=false;setReportBusy(false);}}
 const [selected,setSelected]=useState<Track|null>(null); const [certificateId,setCertificateId]=useState<number|null>(null);
 const [logged,setLogged]=useState(false); const [loginOpen,setLoginOpen]=useState(false); const [provider,setProvider]=useState(""); const [agreements,setAgreements]=useState([false,false,false,false]); const [terms,setTerms]=useState<number|null>(null);
 const [notices,setNotices]=useState<Notice[]>(initialNotices); const [noticeOpen,setNoticeOpen]=useState(false); const [playlistOpen,setPlaylistOpen]=useState(false); const [newPlaylist,setNewPlaylist]=useState("");
 const [current,setCurrent]=useState<Track>(initialTracks[0]); const [playing,setPlaying]=useState(false); const [position,setPosition]=useState(0); const [duration,setDuration]=useState(120); const [volume,setVolume]=useState(70); const [shuffle,setShuffle]=useState(false); const [repeat,setRepeat]=useState(false); const [queue,setQueue]=useState<number[]>(initialTracks.map(t=>t.id));
 const audioRef=useRef<HTMLAudioElement|null>(null); const [month,setMonth]=useState("9"); const [metric,setMetric]=useState("streams");
 const [uploadTitle,setUploadTitle]=useState(""); const [uploadTags,setUploadTags]=useState<string[]>([]); const [tagInput,setTagInput]=useState(""); const [tagError,setTagError]=useState(""); const [uploadTool,setUploadTool]=useState("Suno"); const [created,setCreated]=useState("2026-09-26"); const [description,setDescription]=useState(""); const [uploadFile,setUploadFile]=useState<File|null>(null); const [uploadConsent,setUploadConsent]=useState(false); const [uploadBusy,setUploadBusy]=useState(false); const [dropActive,setDropActive]=useState(false);
 const fileRef=useRef<HTMLInputElement>(null); const [helpOpen,setHelpOpen]=useState(false);
 const liveCurrent=tracks.find(t=>t.id===current.id)||current; const limit=logged?duration:Math.min(60,duration); const previewNotified=useRef(false);
 const audioSource=(t:Track)=>t.audio||`/audio/${t.art}${logged?"":"-preview"}.mp3`;
 function previewComplete(){const a=audioRef.current;if(a)a.pause();setPlaying(false);if(!previewNotified.current){previewNotified.current=true;setSelected(null);setLoginOpen(true);toast("1분 미리듣기가 끝났어요. 로그인하고 전체 음악을 들어보세요.");}}
 useEffect(()=>{const a=audioRef.current;if(!a)return;a.pause();setPlaying(false);setPosition(0);previewNotified.current=false;a.src=audioSource(current);a.load();},[logged]);
 useEffect(()=>{if(!mobile?.blockedArtists?.includes(current.artist))return;audioRef.current?.pause();setPlaying(false);setPosition(0);setSelected(null);setReportTrack(null);const next=allTracks.find(t=>!mobile.blockedArtists?.includes(t.artist));if(next)setCurrent(next);},[mobile?.blockedArtists,current.artist,allTracks]);
 const periodStreams=(t:Track,period:string)=>period==="weekly"?(t.weeklyStreams||0):(t.monthlyStreams||0);
 const ranked=(list:Track[],period:string)=>[...list].sort((a,b)=>periodStreams(b,period)-periodStreams(a,period)||a.id-b.id);
 const homeRanking=ranked(tracks.filter(t=>!t.pending),homePeriod).slice(0,10);
 const latestTracks=[...tracks].filter(t=>!t.pending).sort((a,b)=>Date.parse(b.registeredAt||"1970-01-01")-Date.parse(a.registeredAt||"1970-01-01")||b.id-a.id);
 const availableTags=Array.from(new Map(tracks.flatMap(t=>t.tags).map(tag=>[tag.toLowerCase(),tag])).values());
 const filtered=tracks.filter(t=>(genre==="전체"||t.tags.some(tag=>tag.toLowerCase()===genre.toLowerCase()))&&`${t.title} ${t.artist} ${t.tags.join(" ")}`.toLowerCase().includes(query.replace(/^#/,"").toLowerCase()));
 function TagList({t}:{t:Track}){return <span className="track-hashtags">{t.tags.map(tag=><span key={tag.toLowerCase()}>#{tag}</span>)}</span>;}
 function addTags(){const result=mergeHashtags(uploadTags,tagInput);setTagError(result.error);if(result.error)return;setUploadTags(result.tags);setTagInput("");if(result.duplicates)toast("중복 해시태그는 제외했어요.");}
 useEffect(()=>{const readHash=()=>{const h=location.hash.slice(1) as View;if([...(mobile?.localLibrary?[]:["library"]),"dashboard","upload"].includes(h)&&!logged){setView("discover");setLoginOpen(true);history.replaceState(null,"","#discover");return;}if(["discover","charts","library","dashboard","upload"].includes(h))setView(h);};readHash();addEventListener("hashchange",readHash);return()=>removeEventListener("hashchange",readHash);},[logged]);
 useEffect(()=>{if(audioRef.current)audioRef.current.volume=volume/100;},[volume]);
 const navigate=(v:View)=>{if([...(mobile?.localLibrary?[]:["library"]),"dashboard","upload"].includes(v)&&!logged){setLoginOpen(true);return;}setSearchActive(false);setView(v);setQuery("");setGenre("전체");history.replaceState(null,"",`#${v}`);window.scrollTo({top:0,behavior:"smooth"});};
 const requireLogin=()=>{if(!logged){setSelected(null);setLoginOpen(true);return false;}return true;};
 const notify=(title:string,description:string,track:number,kind:Notice["kind"]="music")=>setNotices(n=>[{id:Date.now(),title,description,track,read:false,kind},...n]);
 const toggleSave=(t:Track)=>{if(!mobile?.localLibrary&&!requireLogin())return;setSaved(s=>s.includes(t.id)?s.filter(i=>i!==t.id):[...s,t.id]);toast(saved.includes(t.id)?"찜을 해제했어요":"찜한 음악에 저장했어요");};
 async function play(t:Track,newQueue?:number[]){if(mobile?.blockedArtists?.includes(t.artist))return;const a=audioRef.current;if(!a)return;if(newQueue)setQueue(newQueue);if(current.id===t.id&&playing){a.pause();setPlaying(false);return;}if(current.id!==t.id){setCurrent(t);setPosition(0);previewNotified.current=false;a.src=audioSource(t);a.load();}else if(a.currentTime>=limit){a.currentTime=0;previewNotified.current=false;}try{await a.play();setPlaying(true);}catch{toast.error("음원을 재생할 수 없어요. 다시 눌러주세요.");}}
 function nextTrack(back=false){const playableQueue=queue.filter(id=>tracks.some(t=>t.id===id));if(!playableQueue.length){audioRef.current?.pause();return;}let index=playableQueue.indexOf(current.id);index=shuffle?Math.floor(Math.random()*playableQueue.length):(index+(back?-1:1)+playableQueue.length)%playableQueue.length;const t=tracks.find(x=>x.id===playableQueue[index]);if(t){setCurrent(t);setPosition(0);const a=audioRef.current;if(a){previewNotified.current=false;a.src=audioSource(t);a.load();a.play().then(()=>setPlaying(true)).catch(()=>setPlaying(false));}}}
 function tick(){const a=audioRef.current;if(!a)return;if(!logged&&a.currentTime>=60){a.currentTime=60;setPosition(60);previewComplete();return;}setPosition(a.currentTime);}
 async function share(t:Track){if(mobile){try{await mobile.shareTrack(t.title,t.id);}catch{/* Dismissal leaves playback and counts unchanged. */}return;}try{await navigator.clipboard.writeText(`${location.origin}/#track-${t.id}`);setTracks(ts=>ts.map(x=>x.id===t.id?{...x,shares:x.shares+1}:x));toast.success("음원 링크를 복사했어요");}catch{toast("공유 주소",{description:`${location.origin}/#track-${t.id}`,duration:10000});}}
 useEffect(()=>{const match=location.hash.match(/^#track-(\d+)$/);if(match){const t=initialTracks.find(t=>t.id===+match[1]&&!mobile?.blockedArtists?.includes(t.artist));if(t)setSelected(t);}},[]);
 function pickFile(file?:File){if(!file)return;if(!file.type.startsWith("audio/")){toast.error("MP3, WAV 등 오디오 파일을 선택해 주세요.");return;}if(file.size>50*1024*1024){toast.error("음원 파일은 50MB 이하로 선택해 주세요.");return;}setUploadFile(file);if(!uploadTitle)setUploadTitle(file.name.replace(/\.[^.]+$/,""));}
 async function submitUpload(){const tagResult=mergeHashtags(uploadTags,tagInput);if(tagResult.error||tagResult.tags.length<1){setTagError(tagResult.error||"해시태그를 1개 이상 입력해 주세요.");toast.error(tagResult.error||"해시태그를 1개 이상 입력해 주세요.");return;}setUploadTags(tagResult.tags);setTagInput("");setTagError("");if(!requireLogin())return;if(!uploadTitle.trim()||!uploadFile||!uploadConsent){toast.error("음원 파일, 곡 이름과 권리 확인 동의를 입력해 주세요.");return;}setUploadBusy(true);await new Promise(r=>setTimeout(r,1200));const id=Date.now();const t:Track={id,title:uploadTitle.trim(),artist:"새벽수집가",tags:tagResult.tags,art:"ocean",streams:0,shares:0,own:true,registeredAt:new Date().toISOString(),created,tool:uploadTool,description,pending:true,certifiedAt:new Date().toLocaleDateString("ko-KR"),audio:URL.createObjectURL(uploadFile)};setTracks(p=>[t,...p]);notify("음원 등록 접수가 완료됐어요",`${t.title} · AI 생성 및 권리 확인 대기`,id);setUploadBusy(false);setUploadTitle("");setUploadTags([]);setTagInput("");setTagError("");setUploadFile(null);setUploadConsent(false);toast.success("이 브라우저에서 음원을 열었어요",{description:"이 파일은 현재 브라우저에서만 재생됩니다."});setLibraryTab("owned");navigate("library");}
 function TrackMenu({t}:{t:Track}){return <DropdownMenu><DropdownMenuTrigger asChild><button className="icon-button" aria-label={`${t.title} 더 보기`}><MoreHorizontal size={19}/></button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onSelect={()=>setSelected(t)}><Music2/>음원 정보</DropdownMenuItem><DropdownMenuItem onSelect={()=>toggleSave(t)}><Heart/>{saved.includes(t.id)?"찜 해제":"찜하기"}</DropdownMenuItem><DropdownMenuItem onSelect={()=>{if(!mobile?.localLibrary&&!requireLogin())return;if(!playlist.includes(t.id))setPlaylist(p=>[...p,t.id]);toast.success("플레이리스트에 추가했어요");}}><ListMusic/>플레이리스트에 추가</DropdownMenuItem><DropdownMenuItem onSelect={()=>share(t)}><Share2/>공유하기</DropdownMenuItem><DropdownMenuItem onSelect={()=>openReport(t)}><Flag/>신고하기</DropdownMenuItem>{mobile?.onBlockArtist&&<DropdownMenuItem onSelect={()=>{setSelected(null);mobile.onBlockArtist?.(t.artist);}}><ShieldCheck/>{t.artist} 차단</DropdownMenuItem>}</DropdownMenuContent></DropdownMenu>;}
 function TrackCard({t}:{t:Track}){return <article className="track-card"><div className="art-wrap"><button className="art-button" onClick={()=>setSelected(t)}><Cover track={t}/></button><span className="art-tag">AI MUSIC</span><button className="card-play" aria-label={`${t.title} 재생`} onClick={()=>play(t)}>{current.id===t.id&&playing?<Pause fill="currentColor" size={20}/>:<Play fill="currentColor" size={20}/>}</button></div><div className="track-card-title"><button onClick={()=>setSelected(t)}>{t.title}</button><TrackMenu t={t}/></div><p>{t.artist}</p><span className="listen-card-state">{logged?"전체 듣기":"1분 미리듣기"}</span><TagList t={t}/></article>;}
 function TrackRows({list,reorder=false,period}:{list:Track[];reorder?:boolean;period?:string}){return <div className="track-table"><div className="track-table-head"><span>#</span><span>음원</span><span>해시태그</span><span>스트리밍</span><span>재생 시간</span><span/></div>{list.length===0?<div className="empty-state"><Music2/><h3>아직 소리가 비어 있어요</h3><p>마음에 드는 음악을 발견하고 추가해 보세요.</p><button className="btn outline" onClick={()=>navigate("discover")}>음악 둘러보기</button></div>:list.map((t,i)=><div key={t.id} className={`track-row ${current.id===t.id&&playing?"now-playing":""}`}><span className="rank">{current.id===t.id&&playing?<AudioLines size={18}/>:String(i+1).padStart(2,"0")}</span><div className="track-identity"><button className="row-cover" onClick={()=>play(t,list.map(x=>x.id))} aria-label={`${t.title} 재생`}><Cover track={t}/><span><Play size={17} fill="currentColor"/></span></button><button className="track-name" onClick={()=>setSelected(t)}><strong>{t.title}</strong><small>{t.artist}</small></button></div><span className="row-genre"><TagList t={t}/></span><span className="row-streams">{num(period?periodStreams(t,period):t.streams)}</span><span className="row-time">{t.audio?"직접 등록":"2:00"}</span><div className="row-actions">{reorder?<><IconButton label="위로 이동" disabled={i===0} onClick={()=>setPlaylist(p=>{const a=[...p];[a[i-1],a[i]]=[a[i],a[i-1]];return a;})}><ArrowUp size={16}/></IconButton><IconButton label="아래로 이동" disabled={i===list.length-1} onClick={()=>setPlaylist(p=>{const a=[...p];[a[i+1],a[i]]=[a[i],a[i+1]];return a;})}><ArrowDown size={16}/></IconButton><IconButton label="플레이리스트에서 삭제" onClick={()=>setPlaylist(p=>p.filter(id=>id!==t.id))}><X size={16}/></IconButton></>:<><IconButton label={saved.includes(t.id)?`${t.title} 저장 취소`:`${t.title} 저장`} active={saved.includes(t.id)} onClick={()=>toggleSave(t)}><Heart size={18} fill={saved.includes(t.id)?"currentColor":"none"}/></IconButton><TrackMenu t={t}/></>}</div></div>)}</div>;}

 return <SidebarProvider style={{"--sidebar-width":"232px"} as CSSProperties}><AppNavigation playlistName={playlistName} openPlaylist={()=>{setLibraryTab("playlist");navigate("library");}} view={view} navigate={navigate} logged={logged} openLogin={()=>setLoginOpen(true)}/><div className="app-main"><header className="topbar"><div className="mobile-brand"><SidebarTrigger/><button className="mobile-wordmark" onClick={()=>navigate("discover")}>muleaf</button></div><div className="breadcrumb">{navItems.find(n=>n.id===view)?.label||"음원 등록"}<span>/</span><span>새로운 소리의 시작</span></div><div className="top-actions">{mobile?.openSafety&&<IconButton label="개인정보 및 안전" className="safety-button" onClick={mobile.openSafety}><ShieldCheck size={20}/></IconButton>}<div className="search-box"><Search size={17}/><input ref={searchRef} onFocus={()=>setSearchActive(true)} value={query} onChange={e=>{setQuery(e.target.value);if(!["discover","charts"].includes(view))setView("discover");}} placeholder="어떤 소리를 찾고 있나요?" aria-label="음원, 아티스트 검색"/>{query?<button onClick={()=>setQuery("")} aria-label="검색 지우기"><X size={15}/></button>:<span className="search-hint">⌕</span>}</div><IconButton label="알림" onClick={()=>setNoticeOpen(true)} className="notification-button"><Bell size={20}/>{notices.some(n=>!n.read)&&<span/>}</IconButton>{logged?<DropdownMenu><DropdownMenuTrigger asChild><button className="avatar top-avatar" aria-label="내 계정">새</button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onSelect={()=>navigate("dashboard")}>MY 대시보드</DropdownMenuItem><DropdownMenuItem onSelect={()=>{setLogged(false);toast("로그아웃했어요");}}><LogOut/>로그아웃</DropdownMenuItem></DropdownMenuContent></DropdownMenu>:<button className="login-button" onClick={()=>setLoginOpen(true)}>로그인 <ArrowUpRight size={15}/></button>}</div></header>
 <main className={`page-content ${view==="discover"?"music-home":""}`} key={view}>
 {view==="discover"&&<>
 {!query&&<><section className="home-picks"><div className="section-heading"><h1>오늘의 발견</h1><span className="home-overline">YOUR NEXT SOUND</span></div><div className="pick-rail">{[0,1].map(group=><div className="pick-column" key={group}>{tracks.filter(t=>!t.pending).slice(group*3,group*3+3).map((t,i)=><div className="pick-row" key={t.id}><button onClick={()=>setSelected(t)} className="pick-cover"><Cover track={t}/></button><button className="pick-info" onClick={()=>setSelected(t)}><small>{["오늘을 채울 새로운 소리","다시 듣고 싶은 음악","취향을 넓히는 한 곡"][i]}</small><strong>{t.title}</strong><span>{t.artist}</span></button><IconButton label={`${t.title} 추천 재생`} onClick={()=>play(t)}>{current.id===t.id&&playing?<Pause size={23} fill="currentColor"/>:<Play size={23} fill="currentColor"/>}</IconButton></div>)}</div>)}</div></section>
 <AdSlot placement="discover-side"/>
 <section className="reference-chart"><div className="section-heading"><h2>뮤리프 차트 <ChartNoAxesCombined size={23}/></h2><button className="text-button" onClick={()=>{setChartPeriod(homePeriod);navigate("charts");}}>전체보기</button></div><Tabs value={homePeriod} onValueChange={setHomePeriod}><TabsList className="chart-pills"><TabsTrigger value="weekly">주간 TOP</TabsTrigger><TabsTrigger value="monthly">월간 TOP</TabsTrigger></TabsList></Tabs><div className="ranking-rail" key={homePeriod}>{Array.from({length:Math.ceil(homeRanking.length/4)},(_,group)=><div className="ranking-column" key={group}>{homeRanking.slice(group*4,group*4+4).map((t,i)=><div className="ranked-song" key={t.id}><button className="ranked-cover" onClick={()=>setSelected(t)}><Cover track={t}/></button><span className="song-rank">{group*4+i+1}</span><button className="ranked-info" onClick={()=>setSelected(t)}><strong>{t.title}</strong><span>{t.artist}</span></button><IconButton label={`${t.title} 차트 재생`} onClick={()=>play(t,homeRanking.map(x=>x.id))}>{current.id===t.id&&playing?<Pause size={20} fill="currentColor"/>:<Play size={20} fill="currentColor"/>}</IconButton><TrackMenu t={t}/></div>)}</div>)}</div><button className="chart-play-all" onClick={()=>{if(homeRanking[0])play(homeRanking[0],homeRanking.map(t=>t.id));}}><Play size={17} fill="currentColor"/>{homePeriod==="weekly"?"주간":"월간"} TOP 전체듣기</button></section></>}
 <section className="home-recent"><div className="section-heading"><h2>{query?`‘${query}’ 검색 결과`:"최근 등록된 음악"}</h2><button className="text-button" onClick={()=>setShowAllRecent(v=>!v)}>{showAllRecent?"접기":"전체보기"}</button></div><div className="genre-pills">{["전체",...availableTags].map(g=><button key={g} className={genre===g?"active":""} onClick={()=>setGenre(g)}>{g==="전체"?g:`#${g}`}</button>)}</div><div className={`album-rail ${showAllRecent||query?"expanded":""}`}>{(query?filtered:latestTracks.filter(t=>genre==="전체"||t.tags.some(tag=>tag.toLowerCase()===genre.toLowerCase()))).map(t=><div className="album-item" key={t.id}><TrackCard t={t}/>{t.registeredAt&&<p className="registered-date">{new Date(t.registeredAt).toLocaleDateString("ko-KR",{timeZone:"Asia/Seoul",month:"2-digit",day:"2-digit"})} 등록</p>}</div>)}</div>{!filtered.length&&<div className="empty-state"><Search/><h3>검색 결과가 없어요</h3><button className="btn outline" onClick={()=>{setQuery("");setGenre("전체");}}>검색 초기화</button></div>}</section>
 {!query&&<section className="home-mood"><div className="section-heading"><h2>Mood Play</h2><button className="text-button" onClick={()=>{setLibraryTab("playlist");navigate("library");}}>내 플레이리스트</button></div><div className="genre-pills">{["전체","휴식","집중","드라이브"].map(m=><button key={m} className={mood===m?"active":""} onClick={()=>setMood(m)}>{m}</button>)}</div><div className="mood-rail">{[{title:"느리게 흐르는 밤",tag:"#휴식 #Ambient",genre:"Ambient",mood:"휴식"},{title:"온전히 집중하는 시간",tag:"#집중 #Lo-fi",genre:"Lo-fi",mood:"집중"},{title:"도시를 가로지르는 리듬",tag:"#드라이브 #Electronic",genre:"Electronic",mood:"드라이브"},{title:"가볍게 시작하는 하루",tag:"#휴식 #Jazz",genre:"Jazz",mood:"휴식"}].filter(m=>mood==="전체"||m.mood===mood).map(m=>{const list=tracks.filter(t=>!t.pending&&t.tags.includes(m.genre));return list.length?<article className="mood-card" key={m.title}><button onClick={()=>play(list[0],list.map(t=>t.id))} aria-label={`${m.title} 플레이리스트 재생`}><Cover track={list[0]}/><span className="mood-card-shade"/><span className="mood-art-title">{m.title}</span><Play size={25} fill="currentColor"/></button><h3>{m.title}</h3><p>{m.tag} · {list.length}곡</p></article>:null;})}</div></section>}
 </>}
 {view==="charts"&&<><div className="page-heading"><div><div className="eyebrow">THE SOUND OF NOW</div><h1>뮤리프 차트<span className="lime-text">.</span></h1><p>많은 사람들의 하루에 함께한 음악.</p></div><span className="update-label"><span className="status-dot"/> 스트리밍 순</span></div><div className="chart-spotlights">{ranked(filtered,chartPeriod).slice(0,3).map((t,i)=><button className="chart-spotlight" key={t.id} onClick={()=>play(t)}><Cover track={t}/><div className="chart-spotlight-shade"/><span className="big-rank">0{i+1}</span><div><span>{t.tags.map(tag=>`#${tag}`).join(" ")} · {t.artist}</span><h2>{t.title}</h2><small><Headphones size={14}/>{num(periodStreams(t,chartPeriod))} streams</small></div><span className="chart-play"><Play size={20} fill="currentColor"/></span></button>)}</div><div className="section-heading chart-controls"><Tabs value={chartPeriod} onValueChange={setChartPeriod}><TabsList className="sori-tabs"><TabsTrigger value="weekly">주간 차트</TabsTrigger><TabsTrigger value="monthly">월간 차트</TabsTrigger></TabsList></Tabs><button className="btn small outline" onClick={()=>{const list=ranked(filtered,chartPeriod);if(list[0])play(list[0],list.map(t=>t.id));}}><Play size={14}/> 전체 재생</button></div><TrackRows list={ranked(filtered,chartPeriod)} period={chartPeriod}/></>}
 {view==="library"&&<><div className="page-heading"><div><div className="eyebrow">YOUR OWN COLLECTION</div><h1>찜</h1><p>{mobile?"이 기기에 저장한 음악입니다. 앱 삭제 시 목록도 삭제됩니다.":"찜한 음악을 모아 듣고, 플레이리스트로 정리해 보세요."}</p></div><button className="btn outline" onClick={()=>setPlaylistOpen(true)}><Plus size={17}/> 플레이리스트 만들기</button></div><Tabs value={libraryTab} onValueChange={setLibraryTab}><TabsList className="sori-tabs"><TabsTrigger value="saved">찜한 음악 <span>{saved.length}</span></TabsTrigger><TabsTrigger value="playlist">플레이리스트</TabsTrigger>{!mobile&&<><TabsTrigger value="owned">내가 등록한 음악</TabsTrigger><TabsTrigger value="certificates">내 인증서</TabsTrigger></>}</TabsList></Tabs>{libraryTab==="certificates"?<><div className="certificate-collection-heading"><div><h2>음악의 기록을, 한 장에.</h2><p>등록한 음악의 생성일과 등록 기록을 확인하세요.</p></div></div><div className="certificate-grid">{tracks.filter(t=>t.own).map(t=><CertificateCard key={t.id} track={t} compact onOpen={()=>setCertificateId(t.id)}/>)}</div><p className="footnote">서비스 내 음원 등록 기록입니다. 법적 저작권 등록증이나 블록체인 NFT가 아닙니다.</p></>:libraryTab==="playlist"?<><div className="playlist-hero"><div className="playlist-collage">{[3,1,5,4].map(id=><Cover key={id} track={tracks.find(t=>t.id===id)!}/>)}</div><div><span className="eyebrow">MY PLAYLIST</span><h2>{playlistName}</h2><p>{playlist.length}곡 · 새벽수집가</p><button className="btn lime" disabled={!playlist.length} onClick={()=>play(tracks.find(t=>t.id===playlist[0])!,playlist)}><Play size={16} fill="currentColor"/> 순서대로 재생</button></div></div><p className="footnote">화살표로 재생 순서를 바꿀 수 있어요. 곡의 더 보기 메뉴에서 이 목록에 추가하세요.</p><TrackRows list={playlist.map(id=>tracks.find(t=>t.id===id)!).filter(Boolean)} reorder/></>:libraryTab==="owned"?<><div className="notice-inline"><ShieldCheck size={18}/><span>등록 확인서는 내 인증서에서 확인하세요.</span></div><TrackRows list={tracks.filter(t=>t.own)}/></>:<><div className="library-toolbar"><span>{saved.length}곡의 취향이 모였어요</span><button className="btn small lime" disabled={!saved.length} onClick={()=>play(tracks.find(t=>t.id===saved[0])!,saved)}><Play size={14}/> 전체 재생</button></div><TrackRows list={saved.map(id=>tracks.find(t=>t.id===id)!).filter(Boolean)}/></>}</>}
 {view==="dashboard"&&<><div className="page-heading"><div><div className="eyebrow">YOUR SOUND, YOUR GROWTH</div><h1>반가워요, 새벽수집가님<span className="lime-text">.</span></h1><p>당신의 음악이 만들어 낸 순간들을 살펴보세요.</p></div><Select value={month} onValueChange={setMonth}><SelectTrigger className="w-[160px]"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="9">2026년 9월</SelectItem><SelectItem value="8">2026년 8월</SelectItem><SelectItem value="7">2026년 7월</SelectItem></SelectContent></Select></div><div className="stats-grid">{[{label:"총 스트리밍",value:num(month==="9"?30576:month==="8"?24708:19830),icon:Headphones,delta:"선택한 월의 감상 기록"},{label:"총 공유",value:month==="9"?"334":month==="8"?"278":"212",icon:Share2,delta:"함께 나눈 음악의 순간"},{label:"등록한 음악",value:`${tracks.filter(t=>t.own).length}곡`,icon:Music2,delta:"내가 만든 소리"},{label:"보관한 음악",value:`${saved.length}곡`,icon:Library,delta:"다시 듣고 싶은 음악"}].map(s=><div className="stat-card" key={s.label}><span>{s.label}<s.icon size={17}/></span><strong>{s.value}</strong><small>{s.delta}</small></div>)}</div><section className="analytics-card"><div className="section-heading"><div><h2>음악이 닿은 순간</h2><p>{month}월 일별 {metric==="streams"?"스트리밍":"공유"} 추이</p></div><Tabs value={metric} onValueChange={setMetric}><TabsList><TabsTrigger value="streams">스트리밍</TabsTrigger><TabsTrigger value="shares">공유</TabsTrigger></TabsList></Tabs></div><div className="chart-container"><ResponsiveContainer width="100%" height="100%"><AreaChart data={Array.from({length:26},(_,i)=>({day:`${+month}.${i+1}`,value:Math.round((metric==="streams"?1:.025)*(460+Math.sin(i*1.3)*180+i*32+(i%5)*60)*(+month/9))}))} margin={{top:15,right:10,left:-18,bottom:0}}><defs><linearGradient id="streamGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#d2ff65" stopOpacity={.2}/><stop offset="100%" stopColor="#d2ff65" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="#242a34" strokeDasharray="3 6"/><XAxis dataKey="day" tick={{fill:"#9299a7",fontSize:12}} axisLine={false} tickLine={false} minTickGap={42}/><YAxis tick={{fill:"#9299a7",fontSize:12}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:"#1b222d",border:"1px solid #333e4e",borderRadius:10,color:"#f5f6f8"}} labelStyle={{color:"#b6becc"}} formatter={(v)=>[num(Number(v)),metric==="streams"?"스트리밍":"공유"]}/><Area type="monotone" dataKey="value" stroke="#d2ff65" strokeWidth={2.5} fill="url(#streamGradient)" animationDuration={500}/></AreaChart></ResponsiveContainer></div></section><section className="analytics-card"><div className="section-heading"><h2>내 음원 기록</h2><button className="text-button" onClick={()=>{setLibraryTab("certificates");navigate("library");}}>내 인증서 <ArrowUpRight size={16}/></button></div>{tracks.filter(t=>t.own).map(t=><div className="managed-track" key={t.id}><Cover track={t}/><div><strong>{t.title}</strong><small>{t.pending?"등록 접수 · 검토 대기":"등록 완료"}</small></div><button className="btn small outline" onClick={()=>setCertificateId(t.id)}><ShieldCheck size={15}/> 등록 확인서</button></div>)}</section></>}
 {view==="upload"&&<><div className="page-heading"><div><div className="eyebrow">LET YOUR SOUND BE HEARD</div><h1>당신의 소리를 들려주세요.</h1><p>새로운 음악의 시작, 뮤리프와 함께해요.</p></div></div><div className="upload-layout"><form className="upload-form" onSubmit={e=>{e.preventDefault();submitUpload();}}><div className="form-section-title"><span>01</span><h2>음원 파일</h2></div><input ref={fileRef} type="file" accept="audio/*" className="sr-only" onChange={e=>pickFile(e.target.files?.[0])}/><button type="button" className={`upload-zone ${dropActive?"dragging":""}`} onClick={()=>fileRef.current?.click()} onDragOver={e=>{e.preventDefault();setDropActive(true);}} onDragLeave={()=>setDropActive(false)} onDrop={e=>{e.preventDefault();setDropActive(false);pickFile(e.dataTransfer.files?.[0]);}}>{uploadFile?<CheckCircle2 size={32}/>:<Upload size={32}/>}<strong>{uploadFile?uploadFile.name:"음원 파일을 여기에 놓아주세요"}</strong><span>{uploadFile?`${(uploadFile.size/1024/1024).toFixed(1)} MB · 클릭해서 변경`:"또는 클릭해서 파일 선택"}</span><small>MP3, WAV 등 오디오 · 최대 50MB</small></button><div className="form-section-title"><span>02</span><h2>음원 정보</h2></div><label className="field">곡 이름 <span className="required">*</span><input maxLength={60} placeholder="음원의 이름을 입력하세요" value={uploadTitle} onChange={e=>setUploadTitle(e.target.value)}/></label><div className="form-columns"><div className="field hashtag-field"><label htmlFor="genre-hashtags">장르 해시태그 <span className="required">*</span><span className="tag-count">{uploadTags.length}/5</span></label><div className="hashtag-editor"><div className="selected-tags">{uploadTags.map(tag=><span className="tag-chip" key={tag.toLowerCase()}>#{tag}<button type="button" aria-label={`${tag} 해시태그 삭제`} onClick={()=>{setUploadTags(tags=>tags.filter(t=>t!==tag));setTagError("");}}><X size={14}/></button></span>)}</div><div className="tag-entry"><input id="genre-hashtags" value={tagInput} onChange={e=>{setTagInput(e.target.value);setTagError("");}} onKeyDown={e=>{if(e.nativeEvent.isComposing)return;if(e.key==="Enter"||e.key===","){e.preventDefault();addTags();}}} placeholder="#Ambient #Lo-fi" aria-describedby="hashtag-help hashtag-error" aria-invalid={!!tagError}/><button type="button" className="btn small outline" onClick={addTags} disabled={!tagInput.trim()}>추가</button></div></div><p id="hashtag-help" className="tag-help">1~5개 필수 · Enter 또는 추가 버튼으로 입력해요. 대소문자와 # 유무가 달라도 같은 태그는 한 번만 등록돼요.</p><p id="hashtag-error" className="tag-error" role="status">{tagError}</p></div><div className="field"><label>사용한 AI 도구</label><Select value={uploadTool} onValueChange={setUploadTool}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{["Suno","Udio","Stable Audio","기타"].map(g=><SelectItem key={g} value={g}>{g==="전체"?g:`#${g}`}</SelectItem>)}</SelectContent></Select></div></div><div className="field"><label htmlFor="creation-date">생성일</label><input id="creation-date" type="date" value={created} onChange={e=>setCreated(e.target.value)} max="2026-09-26"/></div><label className="field">음원 소개<textarea rows={3} value={description} onChange={e=>setDescription(e.target.value)} placeholder="어떤 영감에서 시작된 음악인가요?" maxLength={400}/></label><div className="form-section-title"><span>03</span><h2>등록 권한 확인</h2></div><label className="check-line"><Checkbox checked={uploadConsent} onCheckedChange={v=>setUploadConsent(v===true)}/><span>음원의 등록·이용 권한을 보유하고 있음을 확인합니다. <em>(필수)</em><small>AI 도구 이용약관 및 원본 소스의 권리를 확인해 주세요.</small></span></label><button className="btn lime submit-upload" type="submit" disabled={uploadBusy||(!uploadTags.length&&!tagInput.trim())}>{uploadBusy?<LoaderCircle className="spin" size={18}/>:<Upload size={18}/>} {uploadBusy?"등록 중":"음원 등록하기"}</button></form><aside className="upload-guide"><span className="inline-label"><ShieldCheck size={18}/> 음원 등록 안내</span><h3>음악의 시작부터,<br/>관리까지 함께해요.</h3><ol><li><b>음원과 생성 정보 등록</b><span>음원 파일, AI 도구와 생성일을 입력해요.</span></li><li><b>AI 생성 및 권리 확인</b><span>생성 증빙과 이용 권한을 확인해 주세요.</span></li><li><b>음원 등록 확인서</b><span>내 보관함에서 생성일과 등록 기록을 확인해요.</span></li></ol><div className="guide-note"><Sparkles size={18}/><p>음원 등록 서비스는 준비 중입니다. 시작되면 이곳에서 음악을 등록할 수 있어요.</p></div></aside></div></>}
 <AdSlot placement={`${view}-footer`}/><footer className="page-footer"><button className="footer-brand" onClick={()=>navigate("discover")}>muleaf</button><span>Beyond music.</span>{mobile?.openSafety&&<button onClick={mobile.openSafety}>개인정보 및 안전</button>}<button onClick={()=>setHelpOpen(true)}>이용 안내 <ArrowUpRight size={13}/></button><small>© 2026 MULEAF. All rights reserved.</small></footer>
 </main></div>

 <nav className="mobile-bottom-nav" aria-label="주요 메뉴"><button className={view==="discover"&&!searchActive?"active":""} onClick={()=>navigate("discover")}><Home/><span>홈</span></button><button className={view==="discover"&&searchActive?"active":""} onClick={()=>{navigate("discover");setSearchActive(true);searchRef.current?.focus();}}><Search/><span>검색</span></button><button className={view==="upload"?"active":""} onClick={()=>navigate("upload")}><Plus/><span>등록하기</span></button><button className={view==="library"?"active":""} onClick={()=>{setLibraryTab("saved");navigate("library");}}><Heart fill={view==="library"?"currentColor":"none"}/><span>찜</span></button><button className={view==="dashboard"?"active":""} onClick={()=>navigate("dashboard")}><UserRound/><span>내정보</span></button></nav>
 {(!mobile||tracks.some(t=>t.id===current.id))&&<><div className="player"><div className="player-track"><button onClick={()=>setSelected(liveCurrent)} className="player-art"><Cover track={current}/></button><div><button onClick={()=>setSelected(liveCurrent)}>{current.title}</button><span>{current.artist}<em className="listen-state">{logged?"전체 듣기":"1분 미리듣기"}</em></span></div><IconButton label={saved.includes(current.id)?"현재 곡 찜 해제":"현재 곡 찜하기"} active={saved.includes(current.id)} onClick={()=>toggleSave(current)} className="player-save"><Heart size={18} fill={saved.includes(current.id)?"currentColor":"none"}/></IconButton></div><div className="player-center"><div className="player-controls"><IconButton label="셔플" active={shuffle} onClick={()=>{setShuffle(!shuffle);toast(!shuffle?"셔플 재생을 켰어요":"순서대로 재생해요");}}><Shuffle size={16}/></IconButton><IconButton label="이전 곡" onClick={()=>nextTrack(true)}><SkipBack size={18} fill="currentColor"/></IconButton><button className="player-main-button" aria-label={playing?"일시 정지":"재생"} onClick={()=>play(current)}>{playing?<Pause size={20} fill="currentColor"/>:<Play size={20} fill="currentColor"/>}</button><IconButton label="다음 곡" onClick={()=>nextTrack()}><SkipForward size={18} fill="currentColor"/></IconButton><IconButton label="한 곡 반복" active={repeat} onClick={()=>{setRepeat(!repeat);toast(!repeat?"한 곡 반복을 켰어요":"반복 재생을 껐어요");}}><Repeat2 size={16}/></IconButton></div><div className="player-timeline"><span>{time(position)}</span><Slider aria-label="재생 위치" value={[Math.min(position,limit)]} max={limit||60} step={1} onValueChange={([v])=>{if(audioRef.current){const target=Math.min(v,limit);audioRef.current.currentTime=target;setPosition(target);if(target<limit)previewNotified.current=false;}}}/><span>{time(limit)}</span></div></div><div className="player-right"><IconButton label={volume===0?"음소거 해제":"음소거"} onClick={()=>setVolume(volume?0:70)}>{volume?<Volume2 size={18}/>:<VolumeX size={18}/>}</IconButton><Slider aria-label="볼륨" value={[volume]} max={100} onValueChange={([v])=>setVolume(v)} className="volume-slider"/><IconButton label="재생 목록" onClick={()=>{navigate("library");setLibraryTab("playlist");}}><ListMusic size={19}/></IconButton></div></div><audio ref={audioRef} src={audioSource(current)} preload="metadata" onTimeUpdate={tick} onLoadedMetadata={()=>{const value=audioRef.current?.duration;if(value&&Number.isFinite(value)){setDuration(value);if(logged)setTracks(ts=>ts.map(t=>t.id===current.id?{...t,durationSeconds:value}:t));}}} onPause={()=>setPlaying(false)} onPlay={()=>setPlaying(true)} onEnded={()=>{if(!logged){previewComplete();return;}if(repeat&&audioRef.current){audioRef.current.currentTime=0;audioRef.current.play().catch(()=>setPlaying(false));}else nextTrack();}}/></>}

 <Dialog open={!!selected} onOpenChange={o=>{if(!o)setSelected(null);}}><DialogContent className="sori-dialog track-dialog"><DialogHeader><DialogTitle>음원 이야기</DialogTitle><DialogDescription>음악과 창작자의 이야기를 만나보세요.</DialogDescription></DialogHeader>{selected&&(()=>{const t=tracks.find(x=>x.id===selected.id)||selected;return <><div className="detail-top"><Cover track={t}/><div><span className="eyebrow">{t.tags.map(tag=>`#${tag}`).join(" ")} · AI MUSIC</span><h2>{t.title}</h2><p>{t.artist}</p><div className="detail-duration"><Clock3 size={16}/><span>음원 길이</span><strong>{t.durationSeconds?time(t.durationSeconds):!t.audio?"2:00":current.id===t.id&&logged?time(duration):"확인 중"}</strong></div><span className="listen-detail-state">{logged?"전체 듣기":"1분 미리듣기 · 로그인하면 전체 듣기"}</span><div className="detail-actions"><button className="btn lime detail-play" onClick={()=>play(t)}>{current.id===t.id&&playing?<Pause size={18} fill="currentColor"/>:<Play size={18} fill="currentColor"/>}{current.id===t.id&&playing?"일시정지":"재생"}</button><IconButton label={saved.includes(t.id)?"음원 찜 해제":"음원 찜하기"} active={saved.includes(t.id)} onClick={()=>toggleSave(t)}><Heart size={19} fill={saved.includes(t.id)?"currentColor":"none"}/></IconButton><IconButton label="음원 공유" onClick={()=>share(t)}><Share2 size={18}/></IconButton><button className="text-button report-trigger" onClick={()=>openReport(t)}><Flag size={16}/> 신고하기</button>{mobile?.onBlockArtist&&<button className="text-button" onClick={()=>{setSelected(null);mobile.onBlockArtist?.(t.artist);}}><ShieldCheck size={16}/>아티스트 차단</button>}</div></div></div>{t.description&&<p className="track-description">{t.description}</p>}<div className="detail-stats"><span><Headphones size={17}/><b>{num(t.streams)}</b> 스트리밍</span><span><Share2 size={17}/><b>{num(t.shares)}</b> 공유</span></div><button className="btn outline certificate-view-button" onClick={()=>{setSelected(null);setCertificateId(t.id);}}><ShieldCheck size={16}/> 등록 확인서 보기</button><AdSlot placement="track-detail"/></>;})()}</DialogContent></Dialog>
 <Dialog open={certificateId!==null} onOpenChange={o=>{if(!o)setCertificateId(null);}}><DialogContent className="sori-dialog certificate-dialog"><DialogHeader><DialogTitle>나의 음악, 나의 기록.</DialogTitle><DialogDescription>음원 등록 확인서</DialogDescription></DialogHeader>{(()=>{const t=tracks.find(t=>t.id===certificateId);return t?<><CertificateCard track={t}/><AdSlot placement="certificate-detail"/></>:null;})()}</DialogContent></Dialog>
 <Dialog open={!!reportTrack} onOpenChange={o=>{if(!o&&!reportBusy)setReportTrack(null);}}><DialogContent className="sori-dialog report-dialog" onEscapeKeyDown={e=>{if(reportBusy)e.preventDefault();}} onInteractOutside={e=>{if(reportBusy)e.preventDefault();}}><DialogHeader><DialogTitle>{reportReceipt?"신고가 접수되었어요":"음원 신고하기"}</DialogTitle><DialogDescription>{reportTrack?.title} · {reportTrack?.artist}</DialogDescription></DialogHeader>{reportReceipt?<div className="report-complete"><CheckCircle2 size={36}/><p>신고 내용은 검토 대상으로 접수됩니다.<br/>신고 접수만으로 음원이 삭제되지는 않습니다.</p><div className="report-receipt"><span>접수번호</span><code>{reportReceipt}</code></div><button className="btn lime full-width" onClick={()=>setReportTrack(null)}>확인</button></div>:<form onSubmit={e=>{e.preventDefault();submitReport();}}><fieldset className="report-reasons" disabled={reportBusy}><legend>신고 사유 <span className="required">*</span></legend>{reportReasons.map(reason=><label key={reason}><input type="radio" name="report-reason" value={reason} checked={reportReason===reason} onChange={()=>{setReportReason(reason);setReportError("");}} required/>{reason}</label>)}</fieldset><label className="field" htmlFor="report-detail">상세 내용 {reportReason==="기타"?"(필수 · 10자 이상)":"(선택)"}<textarea id="report-detail" rows={4} maxLength={1000} disabled={reportBusy} value={reportDetail} onChange={e=>{setReportDetail(e.target.value);setReportError("");}} placeholder="문제가 되는 내용이나 구간을 알려주세요."/></label><div className="report-counter">{reportDetail.length}/1,000</div><p className="footnote">주민등록번호, 전화번호 등 민감한 개인정보는 입력하지 마세요.</p>{reportError&&<p className="report-error" role="alert">{reportError}</p>}<div className="report-buttons"><button type="button" className="btn outline" disabled={reportBusy} onClick={()=>setReportTrack(null)}>취소</button><button type="submit" className="btn lime" disabled={reportBusy||!reportReason||(reportReason==="기타"&&reportDetail.trim().length<10)}>{reportBusy?<><LoaderCircle size={16} className="spin"/> 접수 중</>:"신고 접수"}</button></div></form>}</DialogContent></Dialog>
 <Dialog open={loginOpen} onOpenChange={setLoginOpen}><DialogContent className="sori-dialog login-dialog"><DialogHeader><span className="dialog-brand"><span className="muleaf-mark" aria-hidden="true"/> muleaf</span><DialogTitle>당신의 다음 소리를 만나세요.</DialogTitle><DialogDescription>로그인하고 음악을 끝까지 듣고, 좋아하는 곡을 찜해 보세요.</DialogDescription></DialogHeader><div className="social-buttons"><button className="social naver" onClick={()=>toast("네이버 로그인은 준비 중입니다.")}><b>N</b> 네이버로 시작하기</button><button className="social kakao" onClick={()=>toast("카카오 로그인은 준비 중입니다.")}><span className="kakao-symbol">●</span> 카카오로 시작하기</button><button className="social google" onClick={()=>toast("Google 로그인은 준비 중입니다.")}><b>G</b> Google로 시작하기</button><button className="social apple" onClick={()=>toast("Apple 로그인은 준비 중입니다.")}>Apple로 시작하기</button></div></DialogContent></Dialog>
 <Dialog open={terms!==null} onOpenChange={o=>{if(!o)setTerms(null);}}><DialogContent className="sori-dialog"><DialogHeader><DialogTitle>{["서비스 이용약관","개인정보 수집·이용 안내","마케팅 정보 수신 안내","마케팅 목적 개인정보 이용 안내"][terms??0]}</DialogTitle><DialogDescription>서비스 이용에 필요한 내용을 확인하세요.</DialogDescription></DialogHeader><div className="terms-body">{terms===0?<><h3>서비스 이용</h3><p>뮤리프는 AI 음악을 감상하고 보관하는 서비스입니다.</p><h3>음원과 권리</h3><p>음원 등록 확인서는 서비스 내 등록 정보를 나타냅니다. 저작권 여부는 인간의 창작 기여와 관련 법령에 따라 별도로 판단됩니다.</p></>:terms===1?<><h3>개인정보 처리</h3><p>간편로그인 서비스는 준비 중이며, 현재 소셜 계정 정보는 수집하지 않습니다.</p><h3>회원가입 시</h3><p>제공사에서 동의한 정보만 가져오며, 없는 필수 정보는 별도 인증으로 확인합니다. 수집 항목, 목적, 보유 기간과 동의 거부 시 영향은 정식 약관에서 안내합니다.</p></>:<><h3>선택 동의</h3><p>새 음악, 혜택과 이벤트 안내를 위한 선택 항목입니다. 동의하지 않아도 기본 서비스를 이용할 수 있습니다.</p><p>제3자 제공은 수신자·목적·항목·보유 기간을 명시한 별도 동의 후 적용됩니다.</p></>}</div></DialogContent></Dialog>

 <Sheet open={noticeOpen} onOpenChange={setNoticeOpen}><SheetContent className="notification-sheet"><SheetHeader><SheetTitle>나에게 온 소리 <span className="count">{notices.filter(n=>!n.read).length}</span></SheetTitle><SheetDescription>내 음악의 새로운 소식이에요.</SheetDescription></SheetHeader><button className="text-button mark-read" onClick={()=>setNotices(n=>n.map(x=>({...x,read:true})))}><Check size={15}/> 모두 읽음으로 표시</button><div className="notice-list">{notices.map(n=><button className={`notice-item ${n.read?"read":""}`} key={n.id} onClick={()=>{setNotices(ns=>ns.map(x=>x.id===n.id?{...x,read:true}:x));setNoticeOpen(false);setSelected(tracks.find(t=>t.id===n.track)||null);}}><span className={`notice-icon ${n.kind}`}>{n.kind==="heart"?<Heart size={18}/>:n.kind==="alert"?<TriangleAlert size={18}/>:n.kind==="chart"?<ChartNoAxesCombined size={18}/>:<Music2 size={18}/>}</span><div><strong>{n.title}</strong><p>{n.description}</p></div>{!n.read&&<span className="unread-dot"/>}</button>)}</div></SheetContent></Sheet>
 <Dialog open={playlistOpen} onOpenChange={setPlaylistOpen}><DialogContent className="sori-dialog"><DialogHeader><DialogTitle>나만의 플레이리스트</DialogTitle><DialogDescription>저장한 음악으로 새로운 목록을 시작해요.</DialogDescription></DialogHeader><label className="field">플레이리스트 이름<input value={newPlaylist} onChange={e=>setNewPlaylist(e.target.value)} maxLength={40} placeholder="지금 이 순간의 소리"/></label><p className="footnote">새로 만들면 현재 목록을 교체하고 저장된 음악을 담아요.</p><button className="btn lime full-width" disabled={!newPlaylist.trim()} onClick={()=>{setPlaylistName(newPlaylist.trim());setPlaylist([...saved]);setPlaylistOpen(false);setNewPlaylist("");setLibraryTab("playlist");toast.success("플레이리스트를 만들었어요");}}><Plus size={17}/> 만들기</button></DialogContent></Dialog>
 <Dialog open={helpOpen} onOpenChange={setHelpOpen}><DialogContent className="sori-dialog"><DialogHeader><DialogTitle>뮤리프 이용 안내</DialogTitle><DialogDescription>음악을 발견하고 나만의 취향을 모아보세요.</DialogDescription></DialogHeader><div className="demo-help"><p><Play/>재생 버튼을 눌러 음악을 감상하세요.</p><p><Heart/>마음에 드는 곡은 하트 버튼으로 보관하세요.</p><p><ListMusic/>플레이리스트에서 재생 순서를 바꿀 수 있어요.</p></div><button className="btn lime full-width" onClick={()=>setHelpOpen(false)}>확인</button></DialogContent></Dialog>
 <Toaster position="top-right" theme="dark" richColors closeButton/>
 </SidebarProvider>;
}
